import React from "react";
import { AbsoluteFill, useCurrentFrame, interpolate, spring, Easing } from "remotion";
import { COLORS, FONTS, headlineGradient, ENGRAVE_SHADOW } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const ScanReel: React.FC<PrimitiveProps> = ({ anim, fps, dark, frame }) => {
  const f = useCurrentFrame();
  const S = Math.min(frame.width / 1080, frame.height / 1920);
  const txt = dark ? COLORS.textOnDark : COLORS.textOnLight;
  const muted = dark ? COLORS.mutedOnDark : COLORS.mutedOnLight;

  const heading = String(anim.params?.heading ?? anim.text ?? "Take time to find one that makes sense");
  const rawB = Array.isArray(anim.params?.bullets) ? (anim.params?.bullets as unknown[]) : [];
  const bullets = rawB.map((b) => String(b)).filter((b) => b.length > 0);
  const rows = Math.max(4, Math.min(14, Number(anim.params?.rows ?? 9)));
  const landOn = Math.max(0, Math.min(rows - 1, Number(anim.params?.landOn ?? 5)));

  const rowH = 92 * S;
  const viewH = rowH * 4.2;
  const target = landOn * rowH + rowH / 2 - viewH / 2;
  const offset = interpolate(f, [6, 74], [-rowH * 0.6, target], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.cubic),
  });

  const hs = (heading.length > 34 ? 54 : heading.length > 22 ? 64 : 76) * S;
  const hIn = spring({ frame: f, fps, config: { damping: 200, mass: 0.6 } });
  const panelIn = spring({ frame: f - 4, fps, config: { damping: 200, mass: 0.7 } });

  return (
    <AbsoluteFill style={{ fontFamily: FONTS.body, alignItems: "center", justifyContent: "center" }}>
      <div style={{ width: "84%", display: "flex", flexDirection: "column", alignItems: "center", gap: 40 * S }}>
        <div
          style={{
            fontFamily: FONTS.display,
            fontWeight: FONTS.displayWeight,
            textTransform: "uppercase",
            fontSize: hs,
            lineHeight: 1,
            textAlign: "center",
            backgroundImage: headlineGradient(),
            WebkitBackgroundClip: "text",
            backgroundClip: "text",
            color: "transparent",
            opacity: hIn,
            transform: `translateY(${(1 - hIn) * 24 * S}px)`,
          }}
        >
          {heading}
        </div>

        <div
          style={{
            position: "relative",
            width: "100%",
            height: viewH,
            overflow: "hidden",
            background: COLORS.vellum,
            borderRadius: 22 * S,
            border: `${Math.max(1, 1.2 * S)}px solid rgba(255,255,255,0.10)`,
            boxShadow: "0 20px 50px rgba(0,0,0,0.4)",
            opacity: panelIn,
            transform: `scale(${0.96 + 0.04 * panelIn})`,
          }}
        >
          <div style={{ position: "absolute", left: 0, top: 0, width: "100%", transform: `translateY(${-offset}px)` }}>
            {Array.from({ length: rows }).map((_, i) => {
              const centerY = i * rowH + rowH / 2 - offset;
              const isActive = Math.abs(centerY - viewH / 2) < rowH / 2;
              return (
                <div
                  key={i}
                  style={{
                    height: rowH,
                    display: "flex",
                    alignItems: "center",
                    gap: 20 * S,
                    padding: `0 ${30 * S}px`,
                    opacity: isActive ? 1 : 0.4,
                  }}
                >
                  <div style={{ color: isActive ? COLORS.tealBright : muted, fontFamily: FONTS.mono, fontSize: 20 * S, letterSpacing: 0.14 * 20 * S, width: 60 * S }}>
                    {(i + 1).toString().padStart(2, "0")}
                  </div>
                  <div style={{ display: "flex", alignItems: "center", gap: 4 * S, flex: 1, height: 44 * S }}>
                    {Array.from({ length: 30 }).map((_, j) => {
                      const base = 0.2 + 0.8 * Math.abs(Math.sin(j * 1.47 + i * 2.9));
                      const puls = isActive ? 0.6 + 0.4 * Math.sin(f * 0.24 + j * 0.5) : 1;
                      return (
                        <div
                          key={j}
                          style={{
                            flex: 1,
                            height: Math.max(2, 44 * S * base * puls),
                            borderRadius: 999,
                            background: isActive ? COLORS.teal : COLORS.inkSoft,
                            opacity: isActive ? 0.95 : 0.5,
                          }}
                        />
                      );
                    })}
                  </div>
                </div>
              );
            })}
          </div>

          <div
            style={{
              position: "absolute",
              left: 0,
              top: viewH / 2 - rowH / 2,
              width: "100%",
              height: rowH,
              borderTop: `${Math.max(2, 2 * S)}px solid ${COLORS.teal}`,
              borderBottom: `${Math.max(2, 2 * S)}px solid ${COLORS.teal}`,
              background: "rgba(255,255,255,0.04)",
            }}
          />
        </div>

        <div style={{ width: "100%", display: "flex", flexDirection: "column", gap: 20 * S }}>
          {bullets.map((b, i) => {
            const inn = spring({ frame: f - (70 + i * 12), fps, config: { damping: 200, mass: 0.6 } });
            return (
              <div
                key={i}
                style={{
                  display: "flex",
                  alignItems: "flex-start",
                  gap: 18 * S,
                  opacity: inn,
                  transform: `translateX(${(1 - inn) * -34 * S}px)`,
                }}
              >
                <div style={{ marginTop: 12 * S, width: 14 * S, height: 14 * S, borderRadius: 999, background: COLORS.gold, flex: "0 0 auto" }} />
                <div style={{ color: txt, fontFamily: FONTS.body, fontWeight: FONTS.bodyWeight, fontSize: 30 * S, lineHeight: 1.35, textShadow: ENGRAVE_SHADOW }}>{b}</div>
              </div>
            );
          })}
        </div>

        <div style={{ color: muted, opacity: 0, height: 0 }} />
      </div>
    </AbsoluteFill>
  );
};

export default ScanReel;
